"""Value semantics for minisql.

NULL is represented by Python ``None``.  A value is exactly one of ``None``,
``bool``, ``int``, ``float``, or ``str``.  Booleans are never treated as
numbers, and all invalid operations raise :class:`QueryError`.
"""

import re
from decimal import Decimal, ROUND_HALF_UP, localcontext
from typing import Any, List, Optional, Sequence, Tuple

from .errors import QueryError

AGGREGATES = frozenset({"COUNT", "SUM", "AVG", "MIN", "MAX"})

SCALAR_FUNCTIONS = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}

_COMPARISON_OPS = frozenset({"=", "!=", "<", "<=", ">", ">="})


# ---------------------------------------------------------------------------
# Validation and small helpers


def is_number(value: Any) -> bool:
    """Return True for int/float values, but never for booleans."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _function_name(name: Any) -> str:
    if not isinstance(name, str):
        raise QueryError("invalid function name: %r" % (name,))
    return name.upper()


def check_call(name: str, nargs: int) -> None:
    """Validate a function name and argument count.

    Raises :class:`QueryError` for unknown functions and bad arities.
    ``COUNT(*)`` is handled by the engine separately.
    """
    upper = _function_name(name)
    if not isinstance(nargs, int) or isinstance(nargs, bool):
        raise QueryError("invalid argument count for function %s" % upper)

    if upper in SCALAR_FUNCTIONS:
        minimum, maximum = SCALAR_FUNCTIONS[upper]
        if nargs < minimum or (maximum is not None and nargs > maximum):
            raise QueryError(
                "wrong number of arguments for function %s: %d" % (upper, nargs)
            )
        return

    if upper in AGGREGATES:
        if nargs != 1:
            raise QueryError(
                "wrong number of arguments for function %s: %d" % (upper, nargs)
            )
        return

    raise QueryError("unknown function: %s" % name)


def _type_name(value: Any) -> str:
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, int):
        return "integer"
    if isinstance(value, float):
        return "number"
    if isinstance(value, str):
        return "string"
    return type(value).__name__


def _require_bool(value: Any, operator: str) -> Optional[bool]:
    if value is True or value is False or value is None:
        return value
    raise QueryError(
        "invalid operand for %s: %s" % (operator, _type_name(value))
    )


def _require_string(value: Any, function: str) -> str:
    if not isinstance(value, str):
        raise QueryError(
            "%s requires a string argument, got %s"
            % (function, _type_name(value))
        )
    return value


def _require_number(value: Any, function: str) -> Any:
    if not is_number(value):
        raise QueryError(
            "%s requires a number argument, got %s"
            % (function, _type_name(value))
        )
    return value


def _negate3(result: Optional[bool], negated: bool) -> Optional[bool]:
    if result is None or not negated:
        return result
    return not result


# ---------------------------------------------------------------------------
# Boolean / three-valued logic


def sql_and(a: Any, b: Any) -> Optional[bool]:
    """SQL three-valued AND."""
    a = _require_bool(a, "AND")
    b = _require_bool(b, "AND")
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def sql_or(a: Any, b: Any) -> Optional[bool]:
    """SQL three-valued OR."""
    a = _require_bool(a, "OR")
    b = _require_bool(b, "OR")
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def sql_not(a: Any) -> Optional[bool]:
    """SQL three-valued NOT."""
    a = _require_bool(a, "NOT")
    if a is None:
        return None
    return not a


# ---------------------------------------------------------------------------
# Comparisons and predicates


def compare(a: Any, b: Any) -> int:
    """Compare two non-NULL values, returning -1, 0, or 1."""
    if a is None or b is None:
        raise QueryError("cannot compare NULL values")
    if isinstance(a, bool) and isinstance(b, bool):
        pass
    elif is_number(a) and is_number(b):
        pass
    elif isinstance(a, str) and isinstance(b, str):
        pass
    else:
        raise QueryError(
            "cannot compare %s with %s" % (_type_name(a), _type_name(b))
        )

    if a == b:
        return 0
    if a < b:
        return -1
    return 1


def sql_compare(op: str, a: Any, b: Any) -> Optional[bool]:
    """SQL comparison; NULL operands give NULL."""
    if op == "<>":
        op = "!="
    if op not in _COMPARISON_OPS:
        raise QueryError("invalid comparison operator: %r" % (op,))
    if a is None or b is None:
        return None

    result = compare(a, b)
    if op == "=":
        return result == 0
    if op == "!=":
        return result != 0
    if op == "<":
        return result < 0
    if op == "<=":
        return result <= 0
    if op == ">":
        return result > 0
    return result >= 0


def sql_is_null(a: Any, negated: bool) -> bool:
    """``IS NULL`` / ``IS NOT NULL``; never NULL."""
    result = a is None
    if negated:
        return not result
    return result


def sql_in(value: Any, items: Sequence[Any], negated: bool = False) -> Optional[bool]:
    """SQL ``[NOT] IN`` with left-to-right comparison."""
    if value is None:
        return None

    saw_null = False
    for item in items:
        if item is None:
            saw_null = True
            continue
        if compare(value, item) == 0:
            return _negate3(True, negated)

    return _negate3(None if saw_null else False, negated)


def sql_between(
    value: Any, low: Any, high: Any, negated: bool = False
) -> Optional[bool]:
    """SQL ``[NOT] BETWEEN``: ``low <= value AND value <= high``."""
    result = sql_and(
        sql_compare("<=", low, value),
        sql_compare("<=", value, high),
    )
    return _negate3(result, negated)


def _like_regex(pattern: str) -> str:
    parts = []
    for char in pattern:
        if char == "%":
            parts.append(".*")
        elif char == "_":
            parts.append(".")
        else:
            parts.append(re.escape(char))
    return "".join(parts)


def sql_like(value: Any, pattern: Any, negated: bool = False) -> Optional[bool]:
    """SQL ``[NOT] LIKE`` over the whole string, case-sensitively."""
    if value is None or pattern is None:
        return None
    value = _require_string(value, "LIKE")
    pattern = _require_string(pattern, "LIKE")

    regex = _like_regex(pattern)
    matched = re.fullmatch(regex, value, re.DOTALL) is not None
    return _negate3(matched, negated)


# ---------------------------------------------------------------------------
# Arithmetic


def sql_negate(value: Any) -> Any:
    """Unary minus."""
    if value is None:
        return None
    if isinstance(value, bool) or not is_number(value):
        raise QueryError(
            "cannot negate %s" % _type_name(value)
        )
    return -value


def sql_arithmetic(op: str, a: Any, b: Any) -> Any:
    """Binary ``+``, ``-``, ``*``, and ``/`` with SQL type rules."""
    if op not in ("+", "-", "*", "/"):
        raise QueryError("invalid arithmetic operator: %r" % (op,))
    if a is None or b is None:
        return None
    if not is_number(a) or not is_number(b):
        raise QueryError(
            "cannot apply %s to %s and %s"
            % (op, _type_name(a), _type_name(b))
        )

    if op == "/":
        if b == 0:
            return None
        try:
            return a / b
        except (OverflowError, ZeroDivisionError):
            raise QueryError("numeric overflow in division")

    if isinstance(a, int) and isinstance(b, int):
        if op == "+":
            return a + b
        if op == "-":
            return a - b
        return a * b

    try:
        left = float(a)
        right = float(b)
    except (OverflowError, ValueError):
        raise QueryError("numeric overflow in arithmetic")
    try:
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        return left * right
    except OverflowError:
        raise QueryError("numeric overflow in arithmetic")


def _concat_text(value: Any) -> str:
    if isinstance(value, str):
        return value
    if isinstance(value, bool):
        return "true" if value else "false"
    if is_number(value):
        return str(value)
    raise QueryError(
        "cannot concatenate %s" % _type_name(value)
    )


def sql_concat(a: Any, b: Any) -> Optional[str]:
    """SQL ``||``; NULL operands give NULL."""
    if a is None or b is None:
        return None
    return _concat_text(a) + _concat_text(b)


# ---------------------------------------------------------------------------
# Scalar functions


def _quantize(value: Any, places: int) -> Decimal:
    try:
        number = Decimal(str(value))
    except (ValueError, TypeError, ArithmeticError):
        raise QueryError("cannot round %r" % (value,))

    quantum = Decimal((0, (1,), -places))
    precision = max(28, len(number.as_tuple().digits) + abs(places) + 10)
    try:
        with localcontext() as context:
            context.prec = precision
            return number.quantize(quantum, rounding=ROUND_HALF_UP)
    except (ArithmeticError, ValueError, TypeError):
        raise QueryError("cannot round %r" % (value,))


def call_scalar(name: str, args: Sequence[Any]) -> Any:
    """Call a scalar function with already-evaluated arguments."""
    upper = _function_name(name)
    if upper in AGGREGATES:
        raise QueryError("%s is an aggregate function" % upper)
    check_call(upper, len(args))

    if upper == "LOWER":
        value = args[0]
        if value is None:
            return None
        return _require_string(value, upper).lower()

    if upper == "UPPER":
        value = args[0]
        if value is None:
            return None
        return _require_string(value, upper).upper()

    if upper == "LENGTH":
        value = args[0]
        if value is None:
            return None
        return len(_require_string(value, upper))

    if upper == "ABS":
        value = args[0]
        if value is None:
            return None
        return abs(_require_number(value, upper))

    if upper == "ROUND":
        value = args[0]
        if len(args) == 1:
            if value is None:
                return None
            _require_number(value, upper)
            return int(_quantize(value, 0))

        places = args[1]
        if value is None or places is None:
            return None
        _require_number(value, upper)
        if not isinstance(places, int) or isinstance(places, bool):
            raise QueryError(
                "ROUND requires an integer number of places, got %s"
                % _type_name(places)
            )
        return float(_quantize(value, places))

    # COALESCE: the first non-NULL argument.
    for value in args:
        if value is not None:
            return value
    return None


# ---------------------------------------------------------------------------
# Aggregates


def _non_null_numbers(values: Sequence[Any], function: str) -> List[Any]:
    numbers = []
    for value in values:
        if value is None:
            continue
        if not is_number(value):
            raise QueryError(
                "%s requires numeric values, got %s"
                % (function, _type_name(value))
            )
        numbers.append(value)
    return numbers


def aggregate(name: str, values: Sequence[Any]) -> Any:
    """Compute an aggregate over the evaluated per-row values of one group."""
    upper = _function_name(name)
    if upper not in AGGREGATES:
        if upper in SCALAR_FUNCTIONS:
            raise QueryError("%s is not an aggregate function" % upper)
        raise QueryError("unknown function: %s" % name)
    check_call(upper, 1)

    if upper == "COUNT":
        return sum(1 for value in values if value is not None)

    if upper == "SUM":
        numbers = _non_null_numbers(values, upper)
        if not numbers:
            return None
        total = 0
        for value in numbers:
            total += value
        return total

    if upper == "AVG":
        numbers = _non_null_numbers(values, upper)
        if not numbers:
            return None
        total = 0
        for value in numbers:
            total += value
        try:
            return total / len(numbers)
        except OverflowError:
            raise QueryError("numeric overflow in AVG")

    # MIN / MAX ignore NULLs and preserve the original value.
    non_null = [value for value in values if value is not None]
    if not non_null:
        return None
    best = non_null[0]
    for value in non_null[1:]:
        result = compare(value, best)
        if (upper == "MIN" and result < 0) or (upper == "MAX" and result > 0):
            best = value
    return best


def count_star(n: int) -> int:
    """``COUNT(*)``."""
    return int(n)


# ---------------------------------------------------------------------------
# Grouping, ordering, and output


def _group_component(value: Any) -> Any:
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, int):
        return ("num", value)
    if isinstance(value, float):
        # Normalize integral floats so 1 and 1.0 compare as equal.
        if value.is_integer():
            return ("num", int(value))
        return ("num", value)
    if isinstance(value, str):
        return ("str", value)
    if isinstance(value, (tuple, list)):
        return ("seq", tuple(_group_component(item) for item in value))
    raise QueryError("unsupported value: %r" % (value,))


def group_key(values_tuple: Sequence[Any]) -> Any:
    """A hashable key that groups numerically-equal values together."""
    return tuple(_group_component(value) for value in values_tuple)


def distinct_key(values_tuple: Sequence[Any]) -> Any:
    """A hashable key used for SELECT DISTINCT."""
    return group_key(values_tuple)


def sort_compare(a: Any, b: Any) -> int:
    """Compare two non-NULL sort values; the engine handles NULL placement."""
    return compare(a, b)


def to_csv(value: Any) -> str:
    """Render a value the way the CSV writer expects."""
    if value is None:
        return ""
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)

